package com.speedrunguide;

import java.awt.BasicStroke;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import javax.inject.Inject;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Outlines the dialogue option the current step says to pick.
 */
class DialogueOverlay extends Overlay
{
	private final SpeedrunGuidePlugin plugin;
	private final SpeedrunGuideConfig config;

	@Inject
	DialogueOverlay(SpeedrunGuidePlugin plugin, SpeedrunGuideConfig config)
	{
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		Guide guide = plugin.getGuide();
		Guide.Step step = guide == null ? null : guide.step(plugin.getStep());
		if (!plugin.isActive() || !config.highlightDialogue() || step == null || step.getChat().isEmpty())
		{
			return null;
		}

		graphics.setColor(config.highlightColor());
		graphics.setStroke(new BasicStroke(2));
		for (Widget option : plugin.dialogueOptionWidgets())
		{
			if (GuideText.matches(step.getChat(), option.getText()))
			{
				Rectangle bounds = option.getBounds();
				graphics.drawRect(bounds.x, bounds.y, bounds.width, bounds.height);
			}
		}
		return null;
	}
}

package com.speedrunguide;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import java.awt.Point;
import java.awt.Rectangle;
import java.lang.reflect.Type;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Data;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.config.ConfigManager;

/**
 * Learns which tiles a dig step accepts. The game takes more than the one tile the wiki and
 * RuneLite's clue data give, and nothing documents how much, so each dig is recorded: if the
 * step's item arrives soon after, the tile was good, otherwise it was a miss. Results are saved
 * per item id (the item that dig step waits for) and shared between characters. Misses are kept
 * for the chat report only; the area shown is the rectangle around the good tiles.
 * <p>
 * Only used on the client thread.
 */
@Singleton
class DigLog
{
	private static final String KEY = "digTiles";
	private static final Type TYPE = new TypeToken<Map<Integer, Tiles>>()
	{
	}.getType();
	/** Ticks to wait for the item after the dig animation starts. */
	static final int RESULT_TICKS = 4;

	@Data
	static class Tiles
	{
		private Set<String> good = new LinkedHashSet<>();
		private Set<String> missed = new LinkedHashSet<>();
	}

	enum Result
	{
		GOOD,
		MISSED,
	}

	/** Where the learned tiles are saved: one JSON string. */
	interface Store
	{
		@Nullable
		String load();

		void save(String json);
	}

	private final Store store;
	private final Gson gson;
	private Map<Integer, Tiles> tiles;

	/** The dig waiting for its result; null when none is. */
	@Nullable
	private WorldPoint pendingTile;
	private int pendingItem;
	private int pendingTicks;
	@Nullable
	private WorldPoint lastTile;

	@Inject
	DigLog(ConfigManager configManager, Gson gson)
	{
		this(new Store()
		{
			@Override
			public String load()
			{
				return configManager.getConfiguration(SpeedrunGuideConfig.GROUP, KEY);
			}

			@Override
			public void save(String json)
			{
				configManager.setConfiguration(SpeedrunGuideConfig.GROUP, KEY, json);
			}
		}, gson);
	}

	DigLog(Store store, Gson gson)
	{
		this.store = store;
		this.gson = gson;
	}

	/** A dig started on a tile during a step that waits for this item. */
	void dug(WorldPoint tile, int itemId)
	{
		pendingTile = tile;
		pendingItem = itemId;
		pendingTicks = 0;
	}

	/**
	 * Called every tick with whether the awaited item is now in the inventory.
	 *
	 * @return the result once known, with the tile in {@link #lastTile()}; null while waiting or idle
	 */
	@Nullable
	Result tick(boolean haveItem)
	{
		if (pendingTile == null)
		{
			return null;
		}
		Result result;
		if (haveItem)
		{
			result = Result.GOOD;
		}
		else if (++pendingTicks >= RESULT_TICKS)
		{
			result = Result.MISSED;
		}
		else
		{
			return null;
		}

		Tiles t = tilesFor(pendingItem);
		String key = key(pendingTile);
		if (result == Result.GOOD)
		{
			t.getGood().add(key);
			t.getMissed().remove(key);
		}
		else if (!t.getGood().contains(key))
		{
			// One good dig outweighs misses, which can come from digging a tick too early
			t.getMissed().add(key);
		}
		lastTile = pendingTile;
		pendingTile = null;
		save();
		return result;
	}

	@Nullable
	WorldPoint lastTile()
	{
		return lastTile;
	}

	int pendingItem()
	{
		return pendingTile == null ? 0 : pendingItem;
	}

	Tiles tilesFor(int itemId)
	{
		load();
		return tiles.computeIfAbsent(itemId, k -> new Tiles());
	}

	/**
	 * Where digging works for a step: the rectangle spanned by the route's known tiles and the
	 * tiles learned in game, in world x and y on the step target's floor. Digs seem to work in
	 * rectangles, so finding the corners is enough to fill in the rest.
	 *
	 * @return null if the step isn't a dig or nothing is known yet
	 */
	@Nullable
	Rectangle area(Guide.Step step)
	{
		if (step.getTarget() == null)
		{
			return null;
		}
		int plane = step.getTarget().getPlane();
		List<Point> known = new ArrayList<>();
		for (int[] xy : step.getDigArea())
		{
			known.add(new Point(xy[0], xy[1]));
		}
		if (step.getDone() != null && step.getDone().getHaveId() > 0)
		{
			for (String key : tilesFor(step.getDone().getHaveId()).getGood())
			{
				WorldPoint p = parse(key);
				if (p != null && p.getPlane() == plane)
				{
					known.add(new Point(p.getX(), p.getY()));
				}
			}
		}
		return bounds(known);
	}

	@Nullable
	static Rectangle bounds(List<Point> points)
	{
		Rectangle r = null;
		for (Point p : points)
		{
			if (r == null)
			{
				r = new Rectangle(p.x, p.y, 1, 1);
			}
			else
			{
				r.add(new Rectangle(p.x, p.y, 1, 1));
			}
		}
		return r;
	}

	static String key(WorldPoint p)
	{
		return p.getX() + "," + p.getY() + "," + p.getPlane();
	}

	@Nullable
	static WorldPoint parse(String key)
	{
		String[] parts = key.split(",");
		if (parts.length != 3)
		{
			return null;
		}
		try
		{
			return new WorldPoint(Integer.parseInt(parts[0]), Integer.parseInt(parts[1]), Integer.parseInt(parts[2]));
		}
		catch (NumberFormatException e)
		{
			return null;
		}
	}

	private void load()
	{
		if (tiles != null)
		{
			return;
		}
		String json = store.load();
		Map<Integer, Tiles> loaded = null;
		if (json != null)
		{
			try
			{
				loaded = gson.fromJson(json, TYPE);
			}
			catch (RuntimeException e)
			{
				// A broken save only loses what was learned
			}
		}
		tiles = loaded != null ? loaded : new HashMap<>();
	}

	private void save()
	{
		store.save(gson.toJson(tiles, TYPE));
	}
}

package com.speedrunguide;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import javax.annotation.Nullable;
import lombok.AccessLevel;
import lombok.Data;
import lombok.Getter;
import net.runelite.api.Quest;
import net.runelite.api.coords.WorldPoint;

/**
 * One quest's speedrun guide, as converted from the OSRS Wiki by {@code tools/convert.py}.
 * Text fields hold a tiny HTML subset (b and i tags, escaped entities).
 */
@Getter
public class Guide
{
	static final String WIKI = "https://oldschool.runescape.wiki/w/";

	private String name;
	/** Wiki page title, such as {@code Cook's_Assistant/Speedrun_guide}. */
	private String page;
	private long revision;
	private String start;
	private List<String> skills = Collections.emptyList();
	private List<String> items = Collections.emptyList();
	private List<String> kills = Collections.emptyList();
	/** Trophy tier (bronze, silver, gold, platinum, diamond) to time, such as {@code 3:30}. */
	private Map<String, String> trophies = Collections.emptyMap();
	private List<Section> sections = Collections.emptyList();
	private List<Tip> tips = Collections.emptyList();
	/** Index into {@link #steps()} of the step that starts the quest; earlier steps are set-up. */
	private int startStep;
	/** The variable holding the quest's progress, if the route has steps tied to it. */
	@Nullable
	private Progress progress;

	@Getter(AccessLevel.NONE)
	private transient List<Step> steps;
	@Getter(AccessLevel.NONE)
	private transient Quest quest;
	@Getter(AccessLevel.NONE)
	private transient boolean questLooked;

	@Data
	public static class Section
	{
		private String title;
		private List<Step> steps = Collections.emptyList();
		private List<Image> images = Collections.emptyList();
	}

	@Data
	public static class Step
	{
		private String text;
		private List<String> notes = Collections.emptyList();
		private List<ChatOption> chat = Collections.emptyList();
		/** A remark in the walkthrough rather than something to do. */
		private boolean note;
		/** NPCs to talk to, outlined in the world. */
		private List<String> npcs = Collections.emptyList();
		/** Items to buy, outlined in shops with Buy 1 as their left click. */
		private List<String> shop = Collections.emptyList();
		/** Items to pick up, outlined on the ground. */
		private List<String> ground = Collections.emptyList();
		/** Where the path leads when no matching NPC or ground item is in view. */
		@Nullable
		private Target target;
		/** When the step is finished, so the guide can move on by itself. */
		@Nullable
		private Done done;
		/** Quest progress values at which this is the current step. */
		private List<Integer> progress = Collections.emptyList();
		/** Waypoints the path goes through, in order, before the target. */
		private List<Target> via = Collections.emptyList();
		/** Tiles (x, y on the target's plane) where digging is known to work. */
		private List<int[]> digArea = Collections.emptyList();
		/** Inventory items to use, outlined in the inventory. */
		private List<String> use = Collections.emptyList();
		/** An option made the left click on the step's NPCs, such as Trade. */
		@Nullable
		private String leftClick;
		/** Objects to outline when near the target or a waypoint, such as the wheat or a ladder. */
		private List<String> objects = Collections.emptyList();
		/** A tile filled and labelled on its own, such as where to wait for a wandering NPC. */
		@Nullable
		private Target spot;
		/** A right-click option on the {@link #use} items to color, such as Empty on the compost. */
		@Nullable
		private String useOption;
		/** "south" to only outline (and walk to) the southernmost of the {@link #ground} items and {@link #objects}. */
		@Nullable
		private String pick;
		/** An interface component to outline, such as the Home Teleport spell; 0 means none. */
		private int widget;
		/**
		 * The step arrives somewhere, such as a teleport landing near the target: until within this
		 * many tiles of it, the path and {@link #use} items are hidden and the {@link #widget} is
		 * outlined; after, the other way round. 0 means always arrived.
		 */
		private int pathWithin;
	}

	/** A varbit or varp, as Quest Helper reads it for the quest's progress. */
	@Data
	public static class Progress
	{
		@Nullable
		private Integer varbit;
		@Nullable
		private Integer varp;
	}

	@Data
	public static class Done
	{
		/** An item that is in the inventory once the step is done. */
		@Nullable
		private String have;
		/** An exact item id that is in the inventory once the step is done; 0 means not used. */
		private int haveId;
		/** Getting within this many tiles of the target finishes the step; 0 means not used. */
		private int arrive;
		/** An item that has left the inventory once the step is done, such as grain put in a hopper. */
		@Nullable
		private String lack;
		/** A varbit that reaches {@link #value} once the step is done. */
		@Nullable
		private Integer varbit;
		private int value;
	}

	@Data
	public static class Target
	{
		private int x;
		private int y;
		private int plane;
		private String label;

		WorldPoint worldPoint()
		{
			return new WorldPoint(x, y, plane);
		}
	}

	@Data
	public static class ChatOption
	{
		/** The key to press: a digit for chat options, a letter for some teleport menus, or empty. */
		private String key;
		private String text;
	}

	@Data
	public static class Image
	{
		private String file;
		private String caption;

		String url()
		{
			return WIKI + "File:" + file.replace(' ', '_');
		}
	}

	@Data
	public static class Tip
	{
		@Nullable
		private String heading;
		private List<String> paragraphs = Collections.emptyList();
	}

	/** Every step in order, across sections. */
	List<Step> steps()
	{
		if (steps == null)
		{
			List<Step> all = new ArrayList<>();
			sections.forEach(s -> all.addAll(s.getSteps()));
			steps = Collections.unmodifiableList(all);
		}
		return steps;
	}

	@Nullable
	Step step(int index)
	{
		List<Step> all = steps();
		return index >= 0 && index < all.size() ? all.get(index) : null;
	}

	/** The step that is current when the quest progress has this value; -1 if no step is tied to it. */
	int stepForProgress(int value)
	{
		List<Step> all = steps();
		for (int i = 0; i < all.size(); i++)
		{
			if (all.get(i).getProgress().contains(value))
			{
				return i;
			}
		}
		return -1;
	}

	/**
	 * The steps a progress value allows: from its own step up to (not including) the next step tied
	 * to a progress value. The first one also allows the set-up steps before it.
	 *
	 * @return {from, to}
	 */
	int[] progressRange(int stepIndex)
	{
		List<Step> all = steps();
		boolean first = true;
		for (int i = 0; i < stepIndex; i++)
		{
			if (!all.get(i).getProgress().isEmpty())
			{
				first = false;
				break;
			}
		}
		int to = all.size();
		for (int i = stepIndex + 1; i < all.size(); i++)
		{
			if (!all.get(i).getProgress().isEmpty())
			{
				to = i;
				break;
			}
		}
		return new int[]{first ? 0 : stepIndex, to};
	}

	String url()
	{
		return WIKI + page;
	}

	/** The RuneLite quest this guide is for, used to follow quest progress; null if it can't be matched. */
	@Nullable
	Quest quest()
	{
		if (!questLooked)
		{
			questLooked = true;
			String key = GuideText.normalize(name);
			for (Quest q : Quest.values())
			{
				if (GuideText.normalize(q.getName()).equals(key))
				{
					quest = q;
					break;
				}
			}
		}
		return quest;
	}
}

package com.speedrunguide;

import com.google.gson.Gson;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.io.Reader;
import java.nio.charset.StandardCharsets;
import java.util.Collections;
import java.util.List;
import java.util.stream.Collectors;
import javax.annotation.Nullable;

/**
 * The bundled speedrun guides, in the wiki's order (shortest quests first). Only quests with a
 * hand-checked route are offered for now; the others stay in guides.json until their routes are done.
 */
final class GuideLibrary
{
	private final List<Guide> guides;

	private static class Root
	{
		List<Guide> quests;
	}

	GuideLibrary(List<Guide> guides)
	{
		this.guides = Collections.unmodifiableList(guides);
	}

	/** The quests that have a route (quest progress, paths and highlights). */
	static GuideLibrary load(Gson gson)
	{
		return new GuideLibrary(loadAll(gson).all().stream()
			.filter(g -> g.getProgress() != null)
			.collect(Collectors.toList()));
	}

	/** Every bundled guide, routed or not. */
	static GuideLibrary loadAll(Gson gson)
	{
		try (InputStream in = GuideLibrary.class.getResourceAsStream("guides.json");
			Reader reader = new InputStreamReader(in, StandardCharsets.UTF_8))
		{
			return new GuideLibrary(gson.fromJson(reader, Root.class).quests);
		}
		catch (IOException e)
		{
			throw new IllegalStateException("guides.json is missing from the plugin jar", e);
		}
	}

	List<Guide> all()
	{
		return guides;
	}

	@Nullable
	Guide byName(@Nullable String name)
	{
		for (Guide g : guides)
		{
			if (g.getName().equals(name))
			{
				return g;
			}
		}
		return null;
	}
}

package com.speedrunguide;

import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.GridLayout;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.List;
import java.util.Map;
import javax.swing.BorderFactory;
import javax.swing.BoxLayout;
import javax.swing.JButton;
import javax.swing.JComboBox;
import javax.swing.JComponent;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.SwingConstants;
import javax.swing.SwingUtilities;
import javax.swing.border.Border;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.util.LinkBrowser;

/**
 * Sidebar: pick a quest, see its trophy times and what the speedrun gives you, and click through
 * the wiki's steps. The current step is highlighted; clicking any step makes it the current one.
 */
class GuidePanel extends PluginPanel
{
	private static final String[] TIERS = {"bronze", "silver", "gold", "platinum", "diamond"};
	private static final Color[] TIER_COLORS = {
		new Color(205, 127, 50),
		new Color(192, 192, 192),
		new Color(255, 205, 40),
		new Color(120, 220, 200),
		new Color(170, 230, 255),
	};
	private static final String NOTE_HEX = "#c8c8a0";
	private static final String CHAT_HEX = "#00dcff";
	private static final String MUTED_HEX = "#a0a0a0";
	private static final int TEXT_WIDTH = 150;
	private static final Color DONE_COLOR = new Color(120, 120, 120);
	private static final Border CURRENT_BORDER = BorderFactory.createCompoundBorder(
		BorderFactory.createMatteBorder(0, 3, 0, 0, ColorScheme.BRAND_ORANGE),
		BorderFactory.createEmptyBorder(5, 3, 5, 5));
	private static final Border ROW_BORDER = BorderFactory.createEmptyBorder(5, 6, 5, 5);

	private final SpeedrunGuidePlugin plugin;
	private final JComboBox<String> questBox = new JComboBox<>();
	private final JPanel trophies = new JPanel(new GridLayout(2, 5, 2, 0));
	private final JLabel progress = new JLabel();
	private final JPanel body = new JPanel();
	private final List<JPanel> rows = new ArrayList<>();
	private boolean updatingBox;

	GuidePanel(SpeedrunGuidePlugin plugin)
	{
		this.plugin = plugin;
		setLayout(new BorderLayout(0, 6));
		setBorder(BorderFactory.createEmptyBorder(10, 10, 10, 10));

		JPanel top = new JPanel();
		top.setLayout(new BoxLayout(top, BoxLayout.Y_AXIS));

		JLabel title = new JLabel("Speedrun Quest Guide");
		title.setFont(FontManager.getRunescapeBoldFont());
		title.setForeground(Color.WHITE);
		title.setAlignmentX(LEFT_ALIGNMENT);
		top.add(title);
		top.add(gap(6));

		for (Guide g : plugin.getLibrary().all())
		{
			questBox.addItem(g.getName());
		}
		questBox.setAlignmentX(LEFT_ALIGNMENT);
		questBox.setMaximumSize(new Dimension(Integer.MAX_VALUE, 28));
		questBox.addActionListener(e ->
		{
			Guide picked = plugin.getLibrary().byName((String) questBox.getSelectedItem());
			if (!updatingBox && picked != null && picked != plugin.getGuide())
			{
				plugin.selectGuide(picked);
			}
		});
		top.add(questBox);
		top.add(gap(6));

		trophies.setAlignmentX(LEFT_ALIGNMENT);
		trophies.setToolTipText("Trophy times from the wiki; beat them on the in-game timer");
		top.add(trophies);
		top.add(gap(6));

		JPanel buttons = new JPanel(new GridLayout(1, 4, 3, 0));
		buttons.setAlignmentX(LEFT_ALIGNMENT);
		buttons.add(button("◀", "Previous step", plugin::previous));
		buttons.add(button("▶", "Next step", plugin::next));
		buttons.add(button("↺", "Restart: back to the step that starts the quest", plugin::restart));
		buttons.add(button("Wiki", "Open this guide on the OSRS Wiki", () ->
		{
			Guide g = plugin.getGuide();
			if (g != null)
			{
				LinkBrowser.browse(g.url());
			}
		}));
		top.add(buttons);
		top.add(gap(4));

		progress.setAlignmentX(LEFT_ALIGNMENT);
		progress.setFont(FontManager.getRunescapeSmallFont());
		progress.setForeground(Color.LIGHT_GRAY);
		top.add(progress);

		body.setLayout(new BoxLayout(body, BoxLayout.Y_AXIS));
		add(top, BorderLayout.NORTH);
		add(body, BorderLayout.CENTER);
	}

	void showGuide(Guide guide, int step)
	{
		updatingBox = true;
		questBox.setSelectedItem(guide.getName());
		updatingBox = false;

		trophies.removeAll();
		Map<String, String> times = guide.getTrophies();
		for (int i = 0; i < TIERS.length; i++)
		{
			JLabel name = new JLabel(TIERS[i].substring(0, 1).toUpperCase() + TIERS[i].substring(1, Math.min(4, TIERS[i].length())), SwingConstants.CENTER);
			name.setFont(FontManager.getRunescapeSmallFont());
			name.setForeground(TIER_COLORS[i]);
			trophies.add(name);
		}
		for (int i = 0; i < TIERS.length; i++)
		{
			JLabel time = new JLabel(times.getOrDefault(TIERS[i], "-"), SwingConstants.CENTER);
			time.setForeground(TIER_COLORS[i]);
			trophies.add(time);
		}

		body.removeAll();
		rows.clear();
		body.add(collapsible("Given at the start", setupHtml(guide), false));
		body.add(gap(6));

		int index = 0;
		for (Guide.Section section : guide.getSections())
		{
			JLabel heading = new JLabel(section.getTitle());
			heading.setFont(FontManager.getRunescapeBoldFont());
			heading.setForeground(ColorScheme.BRAND_ORANGE);
			heading.setBorder(BorderFactory.createEmptyBorder(6, 0, 3, 0));
			heading.setAlignmentX(LEFT_ALIGNMENT);
			body.add(heading);

			for (Guide.Step s : section.getSteps())
			{
				JPanel row = stepRow(s, index++);
				rows.add(row);
				body.add(row);
				body.add(gap(2));
			}
			for (Guide.Image image : section.getImages())
			{
				body.add(imageLink(image));
			}
		}

		if (!guide.getTips().isEmpty())
		{
			body.add(gap(8));
			body.add(collapsible("Optimizations", tipsHtml(guide), false));
		}

		body.add(gap(10));
		JLabel credit = new JLabel(html("<span style='color:" + MUTED_HEX + "'>Guide from the OSRS Wiki, CC BY-NC-SA 3.0. Click to open.</span>"));
		credit.setFont(FontManager.getRunescapeSmallFont());
		credit.setAlignmentX(LEFT_ALIGNMENT);
		credit.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		credit.addMouseListener(click(() -> LinkBrowser.browse(guide.url())));
		body.add(credit);

		showStep(guide, step);
		revalidate();
		repaint();
	}

	void showStep(Guide guide, int step)
	{
		if (guide != plugin.getGuide() || rows.size() != guide.steps().size())
		{
			return;
		}
		int total = rows.size();
		progress.setText(step >= total ? "Speedrun complete!" : "Step " + (step + 1) + " of " + total);
		for (int i = 0; i < total; i++)
		{
			JPanel row = rows.get(i);
			boolean current = i == step;
			row.setBackground(current ? ColorScheme.DARK_GRAY_HOVER_COLOR : ColorScheme.DARKER_GRAY_COLOR);
			row.setBorder(current ? CURRENT_BORDER : ROW_BORDER);
			Color text = i < step ? DONE_COLOR : Color.WHITE;
			for (java.awt.Component c : row.getComponents())
			{
				c.setForeground(text);
			}
		}
		if (step < total)
		{
			JPanel row = rows.get(step);
			SwingUtilities.invokeLater(() -> body.scrollRectToVisible(row.getBounds()));
		}
	}

	private JPanel stepRow(Guide.Step step, int index)
	{
		JPanel row = new JPanel(new BorderLayout(4, 0));
		row.setAlignmentX(LEFT_ALIGNMENT);
		row.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		row.setToolTipText("Make this the current step");

		JLabel number = new JLabel(step.isNote() ? "" : String.valueOf(index + 1));
		number.setFont(FontManager.getRunescapeSmallFont());
		number.setVerticalAlignment(SwingConstants.TOP);
		number.setPreferredSize(new Dimension(20, 0));
		row.add(number, BorderLayout.WEST);

		StringBuilder sb = new StringBuilder();
		sb.append(step.isNote() ? "<span style='color:" + NOTE_HEX + "'>" + step.getText() + "</span>" : step.getText());
		for (Guide.ChatOption option : step.getChat())
		{
			sb.append("<br><span style='color:").append(CHAT_HEX).append("'><b>")
				.append(option.getKey().isEmpty() ? "•" : GuideText.escape(option.getKey()))
				.append("</b> ").append(GuideText.escape(option.getText())).append("</span>");
		}
		for (String note : step.getNotes())
		{
			sb.append("<br><span style='color:").append(NOTE_HEX).append("'>").append(note).append("</span>");
		}
		JLabel text = new JLabel(html(sb.toString()));
		text.setVerticalAlignment(SwingConstants.TOP);
		row.add(text, BorderLayout.CENTER);

		row.addMouseListener(click(() -> plugin.setStep(index)));
		row.setMaximumSize(new Dimension(Integer.MAX_VALUE, row.getPreferredSize().height));
		return row;
	}

	private JComponent imageLink(Guide.Image image)
	{
		String caption = image.getCaption().isEmpty() ? image.getFile().replaceFirst("\\.\\w+$", "") : image.getCaption();
		JLabel link = new JLabel(html("<u>Image:</u> " + GuideText.escape(caption)));
		link.setFont(FontManager.getRunescapeSmallFont());
		link.setForeground(new Color(140, 180, 255));
		link.setBorder(BorderFactory.createEmptyBorder(2, 6, 2, 0));
		link.setAlignmentX(LEFT_ALIGNMENT);
		link.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
		link.setToolTipText("Open the picture on the OSRS Wiki");
		link.addMouseListener(click(() -> LinkBrowser.browse(image.url())));
		return link;
	}

	private static String setupHtml(Guide guide)
	{
		StringBuilder sb = new StringBuilder();
		sb.append("<b>Start:</b> ").append(guide.getStart());
		list(sb, "Skills", guide.getSkills());
		list(sb, "Items", guide.getItems());
		list(sb, "Fights", guide.getKills());
		return sb.toString();
	}

	private static void list(StringBuilder sb, String title, List<String> items)
	{
		if (items.isEmpty())
		{
			return;
		}
		sb.append("<br><br><b>").append(title).append(":</b>");
		for (String item : items)
		{
			sb.append("<br>").append(item.startsWith("•") ? "&nbsp;&nbsp;" + item : item);
		}
	}

	private static String tipsHtml(Guide guide)
	{
		StringBuilder sb = new StringBuilder();
		for (Guide.Tip tip : guide.getTips())
		{
			if (sb.length() > 0)
			{
				sb.append("<br><br>");
			}
			if (tip.getHeading() != null)
			{
				sb.append("<b>").append(tip.getHeading()).append("</b><br>");
			}
			sb.append(String.join("<br><br>", tip.getParagraphs()));
		}
		return sb.toString();
	}

	/** A heading that shows and hides a block of text. */
	private JPanel collapsible(String title, String contentHtml, boolean open)
	{
		JPanel panel = new JPanel(new BorderLayout());
		panel.setAlignmentX(LEFT_ALIGNMENT);
		panel.setBackground(ColorScheme.DARKER_GRAY_COLOR);

		JLabel header = new JLabel();
		header.setFont(FontManager.getRunescapeBoldFont());
		header.setForeground(Color.WHITE);
		header.setBorder(BorderFactory.createEmptyBorder(5, 6, 5, 6));
		header.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));

		JLabel content = new JLabel(html(contentHtml, TEXT_WIDTH + 20));
		content.setForeground(Color.LIGHT_GRAY);
		content.setBorder(BorderFactory.createEmptyBorder(0, 6, 6, 6));
		content.setVisible(open);

		Runnable label = () -> header.setText((content.isVisible() ? "▾ " : "▸ ") + title);
		label.run();
		header.addMouseListener(click(() ->
		{
			content.setVisible(!content.isVisible());
			label.run();
			panel.setMaximumSize(null);
			panel.setMaximumSize(new Dimension(Integer.MAX_VALUE, panel.getPreferredSize().height));
			body.revalidate();
		}));

		panel.add(header, BorderLayout.NORTH);
		panel.add(content, BorderLayout.CENTER);
		panel.setMaximumSize(new Dimension(Integer.MAX_VALUE, panel.getPreferredSize().height));
		return panel;
	}

	private static JButton button(String text, String tooltip, Runnable action)
	{
		JButton b = new JButton(text);
		b.setToolTipText(tooltip);
		b.setFocusable(false);
		b.addActionListener(e -> action.run());
		return b;
	}

	private static MouseAdapter click(Runnable action)
	{
		return new MouseAdapter()
		{
			@Override
			public void mouseClicked(MouseEvent e)
			{
				if (SwingUtilities.isLeftMouseButton(e))
				{
					action.run();
				}
			}
		};
	}

	private static JComponent gap(int height)
	{
		JPanel gap = new JPanel();
		gap.setOpaque(false);
		gap.setAlignmentX(LEFT_ALIGNMENT);
		gap.setPreferredSize(new Dimension(0, height));
		gap.setMaximumSize(new Dimension(Integer.MAX_VALUE, height));
		return gap;
	}

	private static String html(String body)
	{
		return html(body, TEXT_WIDTH);
	}

	private static String html(String body, int width)
	{
		return "<html><div style='width:" + width + "px'>" + body + "</div></html>";
	}
}

package com.speedrunguide;

import java.util.List;
import java.util.Locale;
import java.util.regex.Pattern;
import java.util.stream.Collectors;
import javax.annotation.Nullable;
import net.runelite.client.util.Text;

/**
 * Text helpers for guide strings, which hold a tiny HTML subset.
 */
final class GuideText
{
	private static final Pattern TAG = Pattern.compile("<[^>]+>");
	// Some dialogue menus number their options ("1. Yes."); the guide only has the text
	private static final Pattern OPTION_NUMBER = Pattern.compile("^\\d+[.:]\\s*");
	private static final Pattern NOT_WORD = Pattern.compile("[^a-z0-9]+");

	private GuideText()
	{
	}

	/** The guide HTML as plain text, for overlays. */
	static String plain(String html)
	{
		return TAG.matcher(html).replaceAll("")
			.replace("&lt;", "<")
			.replace("&gt;", ">")
			.replace("&amp;", "&");
	}

	/** Plain text made safe to put in the guide HTML. */
	static String escape(String text)
	{
		return text.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;");
	}

	/** Lower case letters and digits only, so "What's Wrong?" matches "What's wrong?". */
	static String normalize(String text)
	{
		String s = OPTION_NUMBER.matcher(Text.removeTags(text).trim()).replaceFirst("");
		return NOT_WORD.matcher(s.toLowerCase(Locale.ROOT)).replaceAll("");
	}

	/** The keys of a step's dialogue options, such as "1, 1, 3". */
	static String keys(List<Guide.ChatOption> chat)
	{
		return chat.stream()
			.map(c -> c.getKey().isEmpty() ? "•" : c.getKey())
			.collect(Collectors.joining(", "));
	}

	/** Whether an NPC or item name is one of the step's names, ignoring case, tags and punctuation. */
	static boolean matchesName(List<String> names, @Nullable String name)
	{
		if (name == null || names.isEmpty())
		{
			return false;
		}
		String shown = normalize(name);
		for (String n : names)
		{
			if (normalize(n).equals(shown))
			{
				return true;
			}
		}
		return false;
	}

	/** Whether a dialogue option on screen is one of the step's options. */
	static boolean matches(List<Guide.ChatOption> chat, String option)
	{
		String shown = normalize(option);
		if (shown.isEmpty())
		{
			return false;
		}
		for (Guide.ChatOption c : chat)
		{
			if (normalize(c.getText()).equals(shown))
			{
				return true;
			}
		}
		return false;
	}
}

package com.speedrunguide;

import java.awt.BasicStroke;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Rectangle;
import java.util.List;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;

/**
 * Outlines the items the current step says to buy in an open shop, to use in the inventory
 * (such as the ancient casket to use on Veos), and the step's interface component (such as the
 * Home Teleport spell).
 */
class ItemOverlay extends Overlay
{
	private final Client client;
	private final SpeedrunGuidePlugin plugin;
	private final SpeedrunGuideConfig config;
	private final ItemManager itemManager;
	private final RouteTracker route;

	@Inject
	ItemOverlay(Client client, SpeedrunGuidePlugin plugin, SpeedrunGuideConfig config, ItemManager itemManager, RouteTracker route)
	{
		this.route = route;
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		this.itemManager = itemManager;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		Guide.Step step = plugin.currentStep();
		if (!plugin.isActive() || !config.highlightShop() || step == null)
		{
			return null;
		}
		graphics.setColor(config.highlightColor());
		graphics.setStroke(new BasicStroke(2));
		outline(graphics, InterfaceID.Shopmain.ITEMS, step.getShop());
		// On a step that arrives somewhere (such as a teleport), the spell comes first, then the items
		if (route.isArrived())
		{
			outline(graphics, InterfaceID.Inventory.ITEMS, step.getUse());
		}
		if (step.getWidget() > 0 && (step.getPathWithin() <= 0 || !route.isArrived()))
		{
			Widget widget = client.getWidget(step.getWidget());
			if (widget != null && !widget.isHidden())
			{
				Rectangle bounds = widget.getBounds();
				graphics.drawRect(bounds.x, bounds.y, bounds.width, bounds.height);
			}
		}
		return null;
	}

	private void outline(Graphics2D graphics, int containerId, List<String> names)
	{
		if (names.isEmpty())
		{
			return;
		}
		Widget container = client.getWidget(containerId);
		if (container == null || container.isHidden() || container.getDynamicChildren() == null)
		{
			return;
		}
		for (Widget item : container.getDynamicChildren())
		{
			if (item != null && !item.isHidden() && item.getItemId() > 0
				&& GuideText.matchesName(names, itemManager.getItemComposition(item.getItemId()).getName()))
			{
				Rectangle bounds = item.getBounds();
				graphics.drawRect(bounds.x, bounds.y, bounds.width, bounds.height);
			}
		}
	}
}

package com.speedrunguide;

import java.awt.Point;
import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import net.runelite.api.CollisionDataFlag;

/**
 * Breadth-first search over one plane of the loaded scene's collision flags, in scene
 * coordinates. Targets outside the scene, or that can't be reached, get a path to the reachable
 * tile closest to them, so the path always points the right way and grows as you walk.
 */
final class Pathfinder
{
	// The order the game's own pathing tries directions in: W, E, S, N, SW, SE, NW, NE
	private static final int[] DX = {-1, 1, 0, 0, -1, 1, -1, 1};
	private static final int[] DY = {0, 0, -1, 1, -1, -1, 1, 1};

	private Pathfinder()
	{
	}

	/**
	 * @param flags collision flags by [x][y]
	 * @param reach how close counts as arrived (0 = on the tile, 1 = next to it)
	 * @return the tiles to walk, start excluded; empty if already there or boxed in
	 */
	static List<Point> find(int[][] flags, int startX, int startY, int goalX, int goalY, int reach)
	{
		int width = flags.length;
		int height = flags[0].length;
		if (!inside(startX, startY, width, height))
		{
			return Collections.emptyList();
		}

		int[] previous = new int[width * height];
		Arrays.fill(previous, -1);
		int start = startX * height + startY;
		previous[start] = start;
		ArrayDeque<Integer> queue = new ArrayDeque<>();
		queue.add(start);

		int best = start;
		int bestDistance = distance(startX, startY, goalX, goalY);
		while (!queue.isEmpty())
		{
			int tile = queue.poll();
			int x = tile / height;
			int y = tile % height;
			int d = distance(x, y, goalX, goalY);
			if (d < bestDistance)
			{
				best = tile;
				bestDistance = d;
			}
			if (d <= reach)
			{
				best = tile;
				break;
			}
			for (int i = 0; i < DX.length; i++)
			{
				int nx = x + DX[i];
				int ny = y + DY[i];
				if (inside(nx, ny, width, height) && previous[nx * height + ny] == -1 && canMove(flags, x, y, DX[i], DY[i]))
				{
					previous[nx * height + ny] = tile;
					queue.add(nx * height + ny);
				}
			}
		}

		List<Point> path = new ArrayList<>();
		for (int tile = best; tile != start; tile = previous[tile])
		{
			path.add(new Point(tile / height, tile % height));
		}
		Collections.reverse(path);
		return path;
	}

	/** Chebyshev distance: steps when diagonals count as one. */
	static int distance(int x1, int y1, int x2, int y2)
	{
		return Math.max(Math.abs(x1 - x2), Math.abs(y1 - y2));
	}

	/** One step from (x, y) by (dx, dy), using the same wall and object checks as RuneLite's WorldArea. */
	static boolean canMove(int[][] flags, int x, int y, int dx, int dy)
	{
		int xFlags = CollisionDataFlag.BLOCK_MOVEMENT_FULL;
		int yFlags = CollisionDataFlag.BLOCK_MOVEMENT_FULL;
		int xyFlags = CollisionDataFlag.BLOCK_MOVEMENT_FULL;
		if (dx < 0)
		{
			xFlags |= CollisionDataFlag.BLOCK_MOVEMENT_EAST;
		}
		else if (dx > 0)
		{
			xFlags |= CollisionDataFlag.BLOCK_MOVEMENT_WEST;
		}
		if (dy < 0)
		{
			yFlags |= CollisionDataFlag.BLOCK_MOVEMENT_NORTH;
		}
		else if (dy > 0)
		{
			yFlags |= CollisionDataFlag.BLOCK_MOVEMENT_SOUTH;
		}
		if (dx < 0 && dy < 0)
		{
			xyFlags |= CollisionDataFlag.BLOCK_MOVEMENT_NORTH_EAST;
		}
		else if (dx < 0 && dy > 0)
		{
			xyFlags |= CollisionDataFlag.BLOCK_MOVEMENT_SOUTH_EAST;
		}
		else if (dx > 0 && dy < 0)
		{
			xyFlags |= CollisionDataFlag.BLOCK_MOVEMENT_NORTH_WEST;
		}
		else if (dx > 0 && dy > 0)
		{
			xyFlags |= CollisionDataFlag.BLOCK_MOVEMENT_SOUTH_WEST;
		}

		if (dx != 0 && (flags[x + dx][y] & xFlags) != 0)
		{
			return false;
		}
		if (dy != 0 && (flags[x][y + dy] & yFlags) != 0)
		{
			return false;
		}
		return dx == 0 || dy == 0 || (flags[x + dx][y + dy] & xyFlags) == 0;
	}

	private static boolean inside(int x, int y, int width, int height)
	{
		return x >= 0 && y >= 0 && x < width && y < height;
	}
}

package com.speedrunguide;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import java.awt.Polygon;
import java.awt.Rectangle;
import javax.annotation.Nullable;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.ItemLayer;
import net.runelite.api.NPC;
import net.runelite.api.Perspective;
import net.runelite.api.Point;
import net.runelite.api.TileObject;
import net.runelite.api.coords.LocalPoint;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.ui.overlay.Overlay;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayUtil;
import net.runelite.client.ui.overlay.outline.ModelOutlineRenderer;
import net.runelite.client.util.ColorUtil;

/**
 * Draws the walking path on the ground, fills the tile it leads to (or the whole area a dig
 * works in), and outlines the NPCs to talk to, the items to pick up and the objects to use.
 * Tiles are filled, not outlined.
 */
class RouteOverlay extends Overlay
{
	private static final int OUTLINE_WIDTH = 2;
	private static final int OUTLINE_FEATHER = 4;
	private static final int TARGET_FILL_ALPHA = 110;

	private final Client client;
	private final SpeedrunGuidePlugin plugin;
	private final SpeedrunGuideConfig config;
	private final RouteTracker route;
	private final ModelOutlineRenderer outlines;
	private final DigLog digLog;

	@Inject
	RouteOverlay(Client client, SpeedrunGuidePlugin plugin, SpeedrunGuideConfig config, RouteTracker route, ModelOutlineRenderer outlines, DigLog digLog)
	{
		this.client = client;
		this.plugin = plugin;
		this.config = config;
		this.route = route;
		this.outlines = outlines;
		this.digLog = digLog;
		setPosition(OverlayPosition.DYNAMIC);
		setLayer(OverlayLayer.ABOVE_SCENE);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!plugin.isActive())
		{
			return null;
		}

		Rectangle digArea = config.showDigTiles() ? digArea() : null;
		if (config.showPath())
		{
			Color path = config.pathColor();
			for (WorldPoint wp : route.getPath())
			{
				if (!wp.equals(route.getTarget()) && (digArea == null || !digArea.contains(wp.getX(), wp.getY())))
				{
					fill(graphics, wp, path);
				}
			}
			// The tile under an NPC or item isn't filled; the NPC or item is outlined instead
			if (digArea == null && !route.isTargetOutlined())
			{
				fill(graphics, route.getTarget(), ColorUtil.colorWithAlpha(config.targetColor(), TARGET_FILL_ALPHA));
			}
		}
		if (digArea != null)
		{
			drawDigArea(graphics, digArea);
		}
		if (config.showPath())
		{
			labelTarget(graphics);
			drawSpot(graphics);
		}

		if (config.highlightNpcs())
		{
			Color color = config.npcColor();
			for (NPC npc : route.getNpcs())
			{
				outlines.drawOutline(npc, OUTLINE_WIDTH, color, OUTLINE_FEATHER);
				Point text = npc.getCanvasTextLocation(graphics, npc.getName(), npc.getLogicalHeight() + 40);
				if (text != null)
				{
					OverlayUtil.renderTextLocation(graphics, text, npc.getName(), color);
				}
			}
		}

		if (config.highlightObjects())
		{
			Color color = config.npcColor();
			for (TileObject object : route.getObjects())
			{
				outlines.drawOutline(object, OUTLINE_WIDTH, color, OUTLINE_FEATHER);
			}
		}

		if (config.highlightGroundItems())
		{
			Color color = config.npcColor();
			for (RouteTracker.GroundItem g : route.getItems())
			{
				ItemLayer layer = g.getTile().getItemLayer();
				if (layer != null)
				{
					outlines.drawOutline(layer, g.getItem(), OUTLINE_WIDTH, color, OUTLINE_FEATHER);
				}
			}
		}
		return null;
	}

	/** The dig step's area on this floor, or null when the step isn't a dig or is on another floor. */
	@Nullable
	private Rectangle digArea()
	{
		Guide.Step step = plugin.currentStep();
		if (step == null || step.getTarget() == null || step.getTarget().getPlane() != client.getTopLevelWorldView().getPlane())
		{
			return null;
		}
		return digLog.area(step);
	}

	/** Fills every tile of the area. */
	private void drawDigArea(Graphics2D graphics, Rectangle area)
	{
		int plane = client.getTopLevelWorldView().getPlane();
		Color fill = ColorUtil.colorWithAlpha(config.targetColor(), TARGET_FILL_ALPHA);
		for (int x = area.x; x < area.x + area.width; x++)
		{
			for (int y = area.y; y < area.y + area.height; y++)
			{
				fill(graphics, new WorldPoint(x, y, plane), fill);
			}
		}
	}

	private void labelTarget(Graphics2D graphics)
	{
		// An outlined NPC shows its own name; outlined items and objects need no label
		if (!route.isTargetOutlined())
		{
			label(graphics, route.getTarget(), route.getTargetLabel());
		}
	}

	/** The step's own marked tile, such as where to wait for the Cook. */
	private void drawSpot(Graphics2D graphics)
	{
		Guide.Step step = plugin.currentStep();
		Guide.Target spot = step == null ? null : step.getSpot();
		if (spot == null)
		{
			return;
		}
		fill(graphics, spot.worldPoint(), ColorUtil.colorWithAlpha(config.targetColor(), TARGET_FILL_ALPHA));
		label(graphics, spot.worldPoint(), spot.getLabel());
	}

	private void label(Graphics2D graphics, @Nullable WorldPoint where, @Nullable String label)
	{
		if (where == null || label == null || where.getPlane() != client.getTopLevelWorldView().getPlane())
		{
			return;
		}
		LocalPoint local = LocalPoint.fromWorld(client.getTopLevelWorldView(), where);
		Point text = local == null ? null : Perspective.getCanvasTextLocation(client, graphics, local, label, 0);
		if (text != null)
		{
			OverlayUtil.renderTextLocation(graphics, text, label, Color.WHITE);
		}
	}

	private void fill(Graphics2D graphics, @Nullable WorldPoint wp, Color color)
	{
		if (wp == null || wp.getPlane() != client.getTopLevelWorldView().getPlane())
		{
			return;
		}
		Polygon poly = tile(wp);
		if (poly != null)
		{
			graphics.setColor(color);
			graphics.fill(poly);
		}
	}

	@Nullable
	private Polygon tile(WorldPoint wp)
	{
		LocalPoint local = LocalPoint.fromWorld(client.getTopLevelWorldView(), wp);
		return local == null ? null : Perspective.getCanvasTilePoly(client, local);
	}
}

package com.speedrunguide;

import java.awt.Point;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import java.util.function.Function;
import javax.annotation.Nullable;
import javax.inject.Inject;
import javax.inject.Singleton;
import lombok.Getter;
import lombok.Value;
import net.runelite.api.Client;
import net.runelite.api.CollisionData;
import net.runelite.api.CollisionDataFlag;
import net.runelite.api.GameObject;
import net.runelite.api.NPC;
import net.runelite.api.ObjectComposition;
import net.runelite.api.Player;
import net.runelite.api.Scene;
import net.runelite.api.Tile;
import net.runelite.api.TileItem;
import net.runelite.api.TileObject;
import net.runelite.api.WorldView;
import net.runelite.api.coords.WorldPoint;
import net.runelite.client.game.ItemManager;

/**
 * Works out, once per tick, what the current step points at: the NPCs to talk to, ground items
 * to pick up and objects to use that are in view, where to walk, and the path there. Runs and is read on the
 * client thread.
 */
@Singleton
class RouteTracker
{
	@Value
	static class GroundItem
	{
		Tile tile;
		TileItem item;
	}

	/** Tiles from a waypoint that count as being there. */
	private static final int WAYPOINT_REACH = 2;
	/** How far around you ground items and objects are looked for. */
	private static final int SCAN_RADIUS = 20;
	/** Objects count when this close to the target or a waypoint, so a whole wheat field or every ladder isn't outlined. */
	private static final int OBJECT_NEAR = 6;

	private final Client client;
	private final ItemManager itemManager;
	/** Object names by id; objects that change with varbits (impostors) aren't cached. */
	private final Map<Integer, String> objectNames = new HashMap<>();

	@Getter
	private List<NPC> npcs = Collections.emptyList();
	@Getter
	private List<GroundItem> items = Collections.emptyList();
	@Getter
	private List<TileObject> objects = Collections.emptyList();
	/** Where the path leads; null if the step has nowhere to go. */
	@Getter
	@Nullable
	private WorldPoint target;
	@Getter
	@Nullable
	private String targetLabel;
	/** The target is an NPC, ground item or object in view, which is outlined already. */
	@Getter
	private boolean targetOutlined;
	@Getter
	private List<WorldPoint> path = Collections.emptyList();
	/** Within the step's {@link Guide.Step#getPathWithin()} range, such as after a teleport lands. */
	@Getter
	private boolean arrived = true;

	private WorldPoint pathFrom;
	private List<WorldPoint> pathGoals;

	@Inject
	RouteTracker(Client client, ItemManager itemManager)
	{
		this.client = client;
		this.itemManager = itemManager;
	}

	void sceneCleared()
	{
		objectNames.clear();
		clear();
	}

	void clear()
	{
		npcs = Collections.emptyList();
		items = Collections.emptyList();
		objects = Collections.emptyList();
		target = null;
		targetLabel = null;
		targetOutlined = false;
		arrived = true;
		path = Collections.emptyList();
		pathFrom = null;
		pathGoals = null;
	}

	void update(@Nullable Guide.Step step, boolean wantPath)
	{
		Player player = client.getLocalPlayer();
		WorldView view = client.getTopLevelWorldView();
		if (step == null || player == null || view == null)
		{
			clear();
			return;
		}
		WorldPoint here = player.getWorldLocation();

		List<NPC> foundNpcs = new ArrayList<>();
		if (!step.getNpcs().isEmpty())
		{
			for (NPC npc : view.npcs())
			{
				if (GuideText.matchesName(step.getNpcs(), npc.getName()))
				{
					foundNpcs.add(npc);
				}
			}
		}
		List<GroundItem> foundItems = new ArrayList<>();
		List<TileObject> foundObjects = new ArrayList<>();
		if (!step.getGround().isEmpty() || !step.getObjects().isEmpty())
		{
			scan(view, step, here, foundItems, foundObjects);
		}
		if ("south".equals(step.getPick()))
		{
			foundObjects = southmost(foundObjects, TileObject::getWorldLocation);
			foundItems = southmost(foundItems, g -> g.getTile().getWorldLocation());
		}
		npcs = foundNpcs;
		items = foundItems;
		objects = foundObjects;

		// Something real in view beats the wiki's coordinates, as NPCs wander and items have several spawns
		WorldPoint to = null;
		String label = null;
		int reach = 0;
		List<WorldPoint> goals = Collections.emptyList();
		NPC nearestNpc = nearest(foundNpcs, here);
		GroundItem nearestItem = nearestItem(foundItems, here);
		if (nearestNpc != null)
		{
			to = nearestNpc.getWorldLocation();
			label = nearestNpc.getName();
			reach = 1;
			goals = Collections.singletonList(to);
		}
		else if (nearestItem != null)
		{
			to = nearestItem.getTile().getWorldLocation();
			label = itemManager.getItemComposition(nearestItem.getItem().getId()).getName();
			goals = Collections.singletonList(to);
		}
		else if (step.getPick() != null && !foundObjects.isEmpty())
		{
			to = foundObjects.get(0).getWorldLocation();
			label = step.getTarget() == null ? null : step.getTarget().getLabel();
			reach = 1;
			goals = Collections.singletonList(to);
		}
		else if (step.getTarget() != null)
		{
			to = step.getTarget().worldPoint();
			label = step.getTarget().getLabel();
			goals = goals(step, here, to);
		}
		target = to;
		targetLabel = label;
		targetOutlined = nearestNpc != null || nearestItem != null || objectAt(foundObjects, to);

		// Some paths only make sense after a teleport has landed
		arrived = step.getPathWithin() <= 0 || step.getTarget() == null
			|| withinOnPlane(here, step.getTarget().worldPoint(), step.getPathWithin());
		if (!arrived)
		{
			wantPath = false;
		}
		if (!wantPath || goals.isEmpty())
		{
			path = Collections.emptyList();
			pathFrom = null;
			pathGoals = null;
		}
		else if (!here.equals(pathFrom) || !goals.equals(pathGoals))
		{
			path = chainPath(view, here, goals, reach);
			pathFrom = here;
			pathGoals = goals;
		}
	}

	/**
	 * The points the path should go through from here: on another floor, the first waypoint on
	 * this floor (such as a ladder); on the target's floor, the waypoints not yet passed, then
	 * the target. A waypoint counts as passed once you are closer to the target than it is.
	 */
	static List<WorldPoint> goals(Guide.Step step, WorldPoint here, WorldPoint to)
	{
		if (to.getPlane() != here.getPlane())
		{
			for (Guide.Target via : step.getVia())
			{
				if (via.getPlane() == here.getPlane())
				{
					return Collections.singletonList(via.worldPoint());
				}
			}
			return Collections.emptyList();
		}
		List<WorldPoint> goals = new ArrayList<>();
		int left = here.distanceTo2D(to);
		for (Guide.Target via : step.getVia())
		{
			WorldPoint wp = via.worldPoint();
			if (wp.getPlane() == here.getPlane() && wp.distanceTo2D(to) < left - WAYPOINT_REACH
				&& wp.distanceTo2D(here) > WAYPOINT_REACH)
			{
				goals.add(wp);
			}
		}
		goals.add(to);
		return goals;
	}

	/** Paths from one goal to the next, joined, stopping where a goal is outside the loaded area. */
	private static List<WorldPoint> chainPath(WorldView view, WorldPoint from, List<WorldPoint> goals, int targetReach)
	{
		List<WorldPoint> all = new ArrayList<>();
		WorldPoint at = from;
		for (int i = 0; i < goals.size(); i++)
		{
			WorldPoint goal = goals.get(i);
			boolean last = i == goals.size() - 1;
			int reach = last ? targetReach : WAYPOINT_REACH;
			List<WorldPoint> leg = findPath(view, at, goal, reach);
			all.addAll(leg);
			if (!leg.isEmpty())
			{
				at = leg.get(leg.size() - 1);
			}
			if (at.distanceTo2D(goal) > Math.max(reach, 1))
			{
				break;
			}
		}
		return all;
	}

	private static List<WorldPoint> findPath(WorldView view, WorldPoint from, WorldPoint to, int reach)
	{
		CollisionData[] maps = view.getCollisionMaps();
		if (maps == null || view.isInstance() || maps[view.getPlane()] == null)
		{
			return Collections.emptyList();
		}
		int[][] flags = maps[view.getPlane()].getFlags();
		int baseX = view.getBaseX();
		int baseY = view.getBaseY();
		int goalX = to.getX() - baseX;
		int goalY = to.getY() - baseY;
		// Standing on a blocked tile (an object) is impossible, so arriving next to it is enough
		if (reach == 0 && goalX >= 0 && goalY >= 0 && goalX < flags.length && goalY < flags[0].length
			&& (flags[goalX][goalY] & CollisionDataFlag.BLOCK_MOVEMENT_FULL) != 0)
		{
			reach = 1;
		}

		List<WorldPoint> path = new ArrayList<>();
		for (Point p : Pathfinder.find(flags, from.getX() - baseX, from.getY() - baseY, goalX, goalY, reach))
		{
			path.add(new WorldPoint(p.x + baseX, p.y + baseY, view.getPlane()));
		}
		return path;
	}

	/** Looks through the tiles around you for the step's ground items and objects. */
	private void scan(WorldView view, Guide.Step step, WorldPoint here, List<GroundItem> items, List<TileObject> objects)
	{
		Scene scene = view.getScene();
		Tile[][] tiles = scene.getTiles()[view.getPlane()];
		int baseX = view.getBaseX();
		int baseY = view.getBaseY();
		int cx = here.getX() - baseX;
		int cy = here.getY() - baseY;
		List<WorldPoint> anchors = anchors(step);
		for (int x = Math.max(0, cx - SCAN_RADIUS); x <= Math.min(tiles.length - 1, cx + SCAN_RADIUS); x++)
		{
			for (int y = Math.max(0, cy - SCAN_RADIUS); y <= Math.min(tiles[x].length - 1, cy + SCAN_RADIUS); y++)
			{
				Tile tile = tiles[x][y];
				if (tile == null)
				{
					continue;
				}
				if (!step.getGround().isEmpty() && tile.getGroundItems() != null)
				{
					for (TileItem item : tile.getGroundItems())
					{
						if (GuideText.matchesName(step.getGround(), itemManager.getItemComposition(item.getId()).getName()))
						{
							items.add(new GroundItem(tile, item));
						}
					}
				}
				if (!step.getObjects().isEmpty() && near(tile.getWorldLocation(), anchors))
				{
					for (TileObject object : objectsOn(tile))
					{
						if (GuideText.matchesName(step.getObjects(), objectName(object.getId())))
						{
							objects.add(object);
						}
					}
				}
			}
		}
	}

	private static List<TileObject> objectsOn(Tile tile)
	{
		List<TileObject> found = new ArrayList<>();
		if (tile.getGameObjects() != null)
		{
			for (GameObject object : tile.getGameObjects())
			{
				// Objects bigger than a tile are listed on each of their tiles; keep the one they start on
				if (object != null && object.getSceneMinLocation().equals(tile.getSceneLocation()))
				{
					found.add(object);
				}
			}
		}
		if (tile.getWallObject() != null)
		{
			found.add(tile.getWallObject());
		}
		if (tile.getDecorativeObject() != null)
		{
			found.add(tile.getDecorativeObject());
		}
		if (tile.getGroundObject() != null)
		{
			found.add(tile.getGroundObject());
		}
		return found;
	}

	@Nullable
	private String objectName(int id)
	{
		String cached = objectNames.get(id);
		if (cached != null)
		{
			return cached;
		}
		ObjectComposition def = client.getObjectDefinition(id);
		if (def == null)
		{
			return null;
		}
		if (def.getImpostorIds() != null)
		{
			ObjectComposition impostor = def.getImpostor();
			return impostor == null ? null : impostor.getName();
		}
		objectNames.put(id, def.getName());
		return def.getName();
	}

	/** The step's target and waypoints, which objects have to be near. */
	private static List<WorldPoint> anchors(Guide.Step step)
	{
		List<WorldPoint> anchors = new ArrayList<>();
		if (step.getTarget() != null)
		{
			anchors.add(step.getTarget().worldPoint());
		}
		for (Guide.Target via : step.getVia())
		{
			anchors.add(via.worldPoint());
		}
		return anchors;
	}

	private static boolean near(WorldPoint p, List<WorldPoint> anchors)
	{
		if (anchors.isEmpty())
		{
			return true;
		}
		for (WorldPoint a : anchors)
		{
			if (a.getPlane() == p.getPlane() && a.distanceTo2D(p) <= OBJECT_NEAR)
			{
				return true;
			}
		}
		return false;
	}

	private static <T> List<T> southmost(List<T> things, Function<T, WorldPoint> location)
	{
		if (things.size() < 2)
		{
			return things;
		}
		T south = things.get(0);
		for (T t : things)
		{
			if (location.apply(t).getY() < location.apply(south).getY())
			{
				south = t;
			}
		}
		return Collections.singletonList(south);
	}

	private static boolean withinOnPlane(WorldPoint a, WorldPoint b, int distance)
	{
		return a.getPlane() == b.getPlane() && a.distanceTo2D(b) <= distance;
	}

	/** Whether one of the outlined objects covers or touches the target tile. */
	private static boolean objectAt(List<TileObject> objects, @Nullable WorldPoint to)
	{
		if (to == null)
		{
			return false;
		}
		for (TileObject object : objects)
		{
			if (object.getWorldLocation().getPlane() == to.getPlane() && object.getWorldLocation().distanceTo2D(to) <= 1)
			{
				return true;
			}
		}
		return false;
	}

	@Nullable
	private static NPC nearest(List<NPC> npcs, WorldPoint here)
	{
		NPC best = null;
		int bestDistance = Integer.MAX_VALUE;
		for (NPC npc : npcs)
		{
			int d = npc.getWorldLocation().distanceTo2D(here);
			if (d < bestDistance)
			{
				best = npc;
				bestDistance = d;
			}
		}
		return best;
	}

	@Nullable
	private static GroundItem nearestItem(List<GroundItem> items, WorldPoint here)
	{
		GroundItem best = null;
		int bestDistance = Integer.MAX_VALUE;
		for (GroundItem g : items)
		{
			int d = g.getTile().getWorldLocation().distanceTo2D(here);
			if (d < bestDistance && g.getTile().getWorldLocation().getPlane() == here.getPlane())
			{
				best = g;
				bestDistance = d;
			}
		}
		return best;
	}
}

