		name = "Next step",
		description = "Mark the current step done",
		section = hotkeys,
		position = 0
	)
	default Keybind nextKey()
	{
		return Keybind.NOT_SET;
	}

	@ConfigItem(
		keyName = "previousKey",
		name = "Previous step",
		description = "Go back one step",
		section = hotkeys,
		position = 1
	)
	default Keybind previousKey()
	{
		return Keybind.NOT_SET;
	}
}

package com.speedrunguide;

