import net.runelite.client.util.ImageUtil;

/**
 * Walks through the OSRS Wiki speedrun guide for a Quest Speedrunning quest, one step at a time.
 * The game keeps the time; this only says what to do next. Everything, the sidebar button
 * included, is only active while logged in to a speedrunning world.
 * <p>
 * Threading: {@link #guide} and {@link #step} are read by the overlays on the client thread and
 * changed from both the client thread (quest progress, dialogue) and the Swing thread (panel
 * clicks), so they are volatile and every change goes through {@link #setStep}.
 */
@Slf4j
@PluginDescriptor(
	name = "Speedrun Quest Guide",
	description = "OSRS Wiki speedrun routes for Quest Speedrunning, step by step, with dialogue option highlights",
	tags = {"quest", "speedrun", "speedrunning", "guide", "helper", "trophy", "route", "wiki"}
)
public class SpeedrunGuidePlugin extends Plugin
{
	private static final String SELECTED_KEY = "quest";
	private static final String STEP_KEY_PREFIX = "step.";
	// Short options like "Yes." show up in lots of conversations, so they don't move the guide on
	private static final int MIN_ADVANCE_OPTION_LENGTH = 6;
	private static final int ADVANCE_LOOKAHEAD = 2;
	private static final int AUTO_SELECT_TICKS = 5;
	// Steps whose inventory check is looked at ahead of the current one, so steps without a check get passed
	private static final int DONE_LOOKAHEAD = 2;

	@Inject
	private Client client;

	@Inject
	private SpeedrunGuideConfig config;

	@Inject
	private ConfigManager configManager;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private ClientToolbar clientToolbar;

	@Inject
	private KeyManager keyManager;

	@Inject
	private Gson gson;

	@Inject
	private StepOverlay stepOverlay;

	@Inject
	private DialogueOverlay dialogueOverlay;

	@Inject
	private RouteOverlay routeOverlay;

	@Inject
	private ItemOverlay itemOverlay;

	@Inject
	private RouteTracker route;

	@Inject
	private ClientThread clientThread;

	@Inject
	private ItemManager itemManager;

	@Inject
	private DigLog digLog;

	@Inject
	private ChatMessageManager chatMessageManager;

	@Getter
	private GuideLibrary library;
	private GuidePanel panel;
	private NavigationButton navButton;

	@Getter
	@Nullable
	private volatile Guide guide;
	/** Index into the guide's steps; equal to the step count once the run is done. */
	@Getter
	private volatile int step;
	/** Logged in to a speedrunning world. */
	@Getter
	private volatile boolean active;

	/** The guide's quest state when last checked; null until the first check after login or a guide change. */
	@Nullable
	private QuestState questState;
	/** The guide's quest progress value when last read; null until the first read after login or a guide change. */
	@Nullable
	private Integer questProgress;
	/** The dialogue options seen last tick, so one dialogue only moves the guide once. */
	private List<String> shownOptions = Collections.emptyList();
	private int ticks;

	private final HotkeyListener nextListener = new HotkeyListener(() -> config.nextKey())
	{
		@Override
		public void hotkeyPressed()
		{
			if (active)
			{
				next();
			}
		}
	};

	private final HotkeyListener previousListener = new HotkeyListener(() -> config.previousKey())
	{
		@Override
		public void hotkeyPressed()
		{
			if (active)
			{
				previous();
			}
		}
	};

	@Provides
	SpeedrunGuideConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(SpeedrunGuideConfig.class);
	}

	@Override
	protected void startUp()
	{
		library = GuideLibrary.load(gson);
		Guide saved = library.byName(configManager.getConfiguration(SpeedrunGuideConfig.GROUP, SELECTED_KEY));
		guide = saved != null ? saved : library.all().get(0);
		step = savedStep(guide);

		panel = new GuidePanel(this);
		navButton = NavigationButton.builder()
			.tooltip("Speedrun Quest Guide")
			.icon(ImageUtil.loadImageResource(getClass(), "icon.png"))
			.priority(8)
			.panel(panel)
			.build();

		overlayManager.add(stepOverlay);
		overlayManager.add(dialogueOverlay);
		overlayManager.add(routeOverlay);
		overlayManager.add(itemOverlay);
		keyManager.registerKeyListener(nextListener);
		keyManager.registerKeyListener(previousListener);
		panel.showGuide(guide, step);
		clientThread.invokeLater(this::updateActive);
	}

	@Override
	protected void shutDown()
	{
		keyManager.unregisterKeyListener(nextListener);
		keyManager.unregisterKeyListener(previousListener);
		overlayManager.remove(stepOverlay);
		overlayManager.remove(dialogueOverlay);
		overlayManager.remove(routeOverlay);
		overlayManager.remove(itemOverlay);
		clientToolbar.removeNavigation(navButton);
		active = false;
		questState = null;
		questProgress = null;
		shownOptions = Collections.emptyList();
		clientThread.invokeLater(route::sceneCleared);
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		GameState state = event.getGameState();
		if (state == GameState.LOGIN_SCREEN || state == GameState.HOPPING)
		{
			// A new login or world may be another profile; start the quest comparison over. Loading
			// screens keep it, as resetting a speedrun teleports you through one.
			questState = null;
			questProgress = null;
		}
		if (state == GameState.LOADING)
		{
			route.sceneCleared();
		}
		if (state == GameState.LOGGED_IN || state == GameState.LOGIN_SCREEN)
		{
			updateActive();
		}
	}

	/** Shows the sidebar button and turns the guide on only on speedrunning worlds. */
	private void updateActive()
	{
		boolean now = client.getGameState() == GameState.LOGGED_IN && isSpeedrunWorld();
		if (now == active)
		{
			return;
		}
		active = now;
		if (now)
		{
			clientToolbar.addNavigation(navButton);
		}
		else
		{
			clientToolbar.removeNavigation(navButton);
			route.clear();
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (!active)
		{
			return;
		}
		if (config.autoSelect() && ++ticks % AUTO_SELECT_TICKS == 0)
		{
			selectRunningQuest();
		}
		if (config.followQuest())
		{
			followQuest();
		}
		if (config.advanceOnDialogue())
		{
			advanceOnDialogue();
		}
		Set<Integer> inventory = inventoryIds();
		DigLog.Result dig = digLog.tick(inventory.contains(digLog.pendingItem()));
		if (dig != null && config.logDigs())
		{
			WorldPoint tile = digLog.lastTile();
			chat("Dig at " + tile.getX() + ", " + tile.getY() + (dig == DigLog.Result.GOOD ? " worked." : " missed."));
		}
		if (config.advanceWhenDone())
		{
			advanceWhenDone(inventory);
		}
		route.update(currentStep(), config.showPath());
	}

	/** Moves past steps whose item is now in the inventory, or whose spot has been reached. */
	private void advanceWhenDone(Set<Integer> ids)
	{
		Guide g = guide;
		if (g == null)
		{
			return;
		}
		int current = step;
		Guide.Step now = g.step(current);
		Guide.Done own = now == null ? null : now.getDone();
		Set<String> names = new HashSet<>();
		for (int id : ids)
		{
			names.add(GuideText.normalize(itemManager.getItemComposition(id).getName()));
		}

		// Checks that could already be true before reaching the step only count for the current one
		WorldPoint target = route.getTarget();
		Player player = client.getLocalPlayer();
		if (own != null && ((own.getArrive() > 0 && target != null && player != null
			&& player.getWorldLocation().getPlane() == target.getPlane()
			&& player.getWorldLocation().distanceTo2D(target) <= own.getArrive())
			|| (own.getLack() != null && !names.contains(GuideText.normalize(own.getLack())))
			|| (own.getVarbit() != null && client.getVarbitValue(own.getVarbit()) >= own.getValue())))
		{
			setStep(current + 1);
			return;
		}
		for (int i = current + DONE_LOOKAHEAD; i >= current; i--)
		{
			Guide.Step s = g.step(i);
			Guide.Done done = s == null ? null : s.getDone();
			if (done != null && ((done.getHaveId() > 0 && ids.contains(done.getHaveId()))
				|| (done.getHave() != null && names.contains(GuideText.normalize(done.getHave())))))
			{
				setStep(i + 1);
				return;
			}
		}
	}

	private Set<Integer> inventoryIds()
	{
		Set<Integer> ids = new HashSet<>();
		ItemContainer inventory = client.getItemContainer(InventoryID.INV);
		if (inventory != null)
		{
			for (Item item : inventory.getItems())
			{
				if (item.getId() > 0)
				{
					ids.add(item.getId());
				}
			}
		}
		return ids;
	}

	/** Records digs during a dig step, so {@link DigLog} can learn which tiles work. */
	@Subscribe
	public void onAnimationChanged(AnimationChanged event)
	{
		Player player = client.getLocalPlayer();
		Guide.Step now = currentStep();
		if (!active || event.getActor() != player || player.getAnimation() != AnimationID.HUMAN_DIG
			|| now == null || now.getDone() == null || now.getDone().getHaveId() <= 0)
		{
			return;
		}
		digLog.dug(player.getWorldLocation(), now.getDone().getHaveId());
	}

	private void chat(String message)
	{
		chatMessageManager.queue(QueuedMessage.builder()
			.type(ChatMessageType.GAMEMESSAGE)
			.runeLiteFormattedMessage(new ChatMessageBuilder().append("[Speedrun Guide] " + message).build())
			.build());
	}

	/** Colors the step's option (such as Empty) on the items it says to use, so it stands out in the right-click menu. */
	@Subscribe
	public void onMenuOpened(MenuOpened event)
	{
		Guide.Step now = currentStep();
		if (!active || !config.highlightShop() || now == null || now.getUseOption() == null)
		{
			return;
		}
		String color = ColorUtil.colorToHexCode(config.highlightColor());
		for (MenuEntry e : event.getMenuEntries())
		{
			if (now.getUseOption().equals(e.getOption()) && GuideText.matchesName(now.getUse(), e.getTarget()))
			{
				e.setOption("<col=" + color + ">" + e.getOption() + "</col>");
			}
		}
	}

	/**
	 * Makes Buy 1 the left click on the shop items the step says to buy, and the step's option
	 * (such as Trade) the left click on its NPCs.
	 */
	@Subscribe
	public void onPostMenuSort(PostMenuSort event)
	{
		Guide.Step now = currentStep();
		if (!active || !config.leftClickBuy() || client.isMenuOpen() || now == null
			|| (now.getShop().isEmpty() && now.getLeftClick() == null))
		{
			return;
		}
		Menu menu = client.getMenu();
		MenuEntry[] entries = menu.getMenuEntries();
		// The last entry is the left click
		for (int i = 0; i < entries.length - 1; i++)
		{
			MenuEntry e = entries[i];
			boolean buy = "Buy 1".equals(e.getOption()) && GuideText.matchesName(now.getShop(), e.getTarget());
			boolean npcOption = now.getLeftClick() != null && now.getLeftClick().equals(e.getOption())
				&& e.getNpc() != null && GuideText.matchesName(now.getNpcs(), e.getNpc().getName());
			if (buy || npcOption)
			{
				MenuEntry top = entries[entries.length - 1];
				entries[entries.length - 1] = e;
				entries[i] = top;
				menu.setMenuEntries(entries);
				return;
			}
		}
	}

	@Nullable
	Guide.Step currentStep()
	{
		Guide g = guide;
		return g == null ? null : g.step(step);
	}

	boolean isSpeedrunWorld()
	{
		return client.getWorldType().contains(WorldType.QUEST_SPEEDRUNNING);
	}

	/** Switches to the guide whose quest is in progress, as only the quest being run is on a speedrun profile. */
	private void selectRunningQuest()
	{
		Guide current = guide;
		if (current != null && current.quest() != null && current.quest().getState(client) == QuestState.IN_PROGRESS)
		{
			return;
		}
		for (Guide g : library.all())
		{
			Quest q = g.quest();
			if (g != current && q != null && q.getState(client) == QuestState.IN_PROGRESS)
			{
				log.debug("Speedrun of {} detected", g.getName());
				selectGuide(g);
				return;
			}
		}
	}

	private void followQuest()
	{
		Guide g = guide;
		Quest q = g == null ? null : g.quest();
		if (q == null)
		{
			return;
		}
		QuestState now = q.getState(client);
		QuestState before = questState;
		questState = now;
		if (g.getProgress() != null)
		{
			followProgress(g);
		}
		if (before == null || before == now)
		{
			return;
		}

		if (now == QuestState.FINISHED)
		{
			setStep(g.steps().size());
		}
		else if (g.getProgress() != null)
		{
			// Starting and resetting are covered by the progress value
			return;
		}
		else if (now == QuestState.NOT_STARTED)
		{
			// The speedrun was reset or abandoned
			setStep(g.getStartStep());
		}
		else if (before == QuestState.NOT_STARTED && step <= g.getStartStep())
		{
			setStep(g.getStartStep() + 1);
		}
	}

	/**
	 * Keeps the guide in step with the quest's progress value, the way Quest Helper follows a quest.
	 * This also notices a speedrun reset, which puts the value back to the start.
	 */
	private void followProgress(Guide g)
	{
		Guide.Progress var = g.getProgress();
		int value = var.getVarbit() != null ? client.getVarbitValue(var.getVarbit()) : client.getVarpValue(var.getVarp());
		Integer before = questProgress;
		questProgress = value;
		if (before != null && before == value)
		{
			return;
		}
		int at = g.stepForProgress(value);
		if (at < 0)
		{
			return;
		}
		int[] allowed = g.progressRange(at);
		int current = step;
		if (current < allowed[0] || current >= allowed[1])
		{
			setStep(at);
		}
	}

	private void advanceOnDialogue()
	{
		List<String> options = dialogueOptions();
		if (options.equals(shownOptions))
		{
			return;
		}
		shownOptions = options;

		Guide g = guide;
		int current = step;
		Guide.Step now = g == null ? null : g.step(current);
		if (now == null || options.isEmpty() || options.stream().anyMatch(o -> GuideText.matches(now.getChat(), o)))
		{
			return;
		}
		for (int i = current + 1; i <= current + ADVANCE_LOOKAHEAD; i++)
		{
			Guide.Step ahead = g.step(i);
			if (ahead == null)
			{
				return;
			}
			for (String o : options)
			{
				if (GuideText.normalize(o).length() >= MIN_ADVANCE_OPTION_LENGTH && GuideText.matches(ahead.getChat(), o))
				{
					setStep(i);
					return;
				}
			}
		}
	}

	/** The option widgets of the open dialogue menu, or an empty list if none is open. */
	List<Widget> dialogueOptionWidgets()
	{
		Widget menu = client.getWidget(InterfaceID.Chatmenu.OPTIONS);
		if (menu == null || menu.isHidden())
		{
			return Collections.emptyList();
		}
		Widget[] children = menu.getDynamicChildren();
		List<Widget> options = new ArrayList<>();
		// The first child is the "Select an option" title
		for (int i = 1; children != null && i < children.length; i++)
		{
			Widget w = children[i];
			if (w != null && !w.isHidden() && w.getText() != null && !w.getText().isEmpty())
			{
				options.add(w);
			}
		}
		return options;
	}

	private List<String> dialogueOptions()
	{
		List<String> text = new ArrayList<>();
		for (Widget w : dialogueOptionWidgets())
		{
			text.add(w.getText());
		}
		return text;
	}

	void selectGuide(Guide g)
	{
		guide = g;
		step = savedStep(g);
		questState = null;
		questProgress = null;
		shownOptions = Collections.emptyList();
		configManager.setConfiguration(SpeedrunGuideConfig.GROUP, SELECTED_KEY, g.getName());
		SwingUtilities.invokeLater(() -> panel.showGuide(g, step));
	}

	void setStep(int index)
	{
		Guide g = guide;
		if (g == null)
		{
			return;
		}
		int clamped = Math.max(0, Math.min(index, g.steps().size()));
		step = clamped;
		configManager.setConfiguration(SpeedrunGuideConfig.GROUP, STEP_KEY_PREFIX + GuideText.normalize(g.getName()), clamped);
		SwingUtilities.invokeLater(() -> panel.showStep(g, clamped));
	}

	void next()
	{
		setStep(step + 1);
	}

	void previous()
	{
		setStep(step - 1);
	}

	/** Back to the step that starts the quest, for a fresh attempt. */
	void restart()
	{
		Guide g = guide;
		if (g != null)
		{
			setStep(g.getStartStep());
		}
	}

	private int savedStep(Guide g)
	{
		Integer saved = configManager.getConfiguration(SpeedrunGuideConfig.GROUP, STEP_KEY_PREFIX + GuideText.normalize(g.getName()), Integer.class);
		return saved == null ? 0 : Math.max(0, Math.min(saved, g.steps().size()));
	}
}

package com.speedrunguide;

import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

/**
 * The current step, its dialogue keys and notes, and a peek at the steps after it.
 */
class StepOverlay extends OverlayPanel
{
	static final Color CHAT_COLOR = new Color(0, 220, 255);
	private static final Color NOTE_COLOR = new Color(200, 200, 160);
	private static final Color UPCOMING_COLOR = Color.GRAY;
	private static final Color DONE_COLOR = new Color(80, 220, 80);

	private final SpeedrunGuidePlugin plugin;
	private final SpeedrunGuideConfig config;

	@Inject
	StepOverlay(SpeedrunGuidePlugin plugin, SpeedrunGuideConfig config)
	{
		super(plugin);
		this.plugin = plugin;
		this.config = config;
		setPosition(OverlayPosition.TOP_LEFT);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		Guide guide = plugin.getGuide();
		if (!plugin.isActive() || !config.showOverlay() || guide == null)
		{
			return null;
		}

		int index = plugin.getStep();
		int total = guide.steps().size();
		panelComponent.setPreferredSize(new Dimension(config.overlayWidth(), 0));
		panelComponent.getChildren().add(LineComponent.builder()
			.left(guide.getName())
			.right(Math.min(index + 1, total) + "/" + total)
			.rightColor(Color.LIGHT_GRAY)
			.build());

		Guide.Step step = guide.step(index);
		if (step == null)
		{
			panelComponent.getChildren().add(TitleComponent.builder()
				.text("Speedrun complete!")
				.color(DONE_COLOR)
				.build());
			return super.render(graphics);
		}

		panelComponent.getChildren().add(LineComponent.builder()
			.left(GuideText.plain(step.getText()))
			.leftColor(step.isNote() ? NOTE_COLOR : Color.WHITE)
			.build());
		if (!step.getChat().isEmpty())
		{
			panelComponent.getChildren().add(LineComponent.builder()
				.left("Chat: " + GuideText.keys(step.getChat()))
				.leftColor(CHAT_COLOR)
				.build());
		}
		if (config.showNotes())
		{
			for (String note : step.getNotes())
			{
				panelComponent.getChildren().add(LineComponent.builder()
					.left(GuideText.plain(note))
					.leftColor(NOTE_COLOR)
					.build());
			}
		}

		for (int i = 1; i <= config.upcomingSteps(); i++)
		{
			Guide.Step upcoming = guide.step(index + i);
			if (upcoming == null)
			{
				break;
			}
			panelComponent.getChildren().add(LineComponent.builder()
				.left((i == 1 ? "Next: " : "Then: ") + GuideText.plain(upcoming.getText()))
				.leftColor(UPCOMING_COLOR)
				.build());
		}
		return super.render(graphics);
	}
}

package com.speedrunguide;

import com.google.gson.Gson;
import java.awt.Rectangle;
import java.util.Arrays;
import net.runelite.api.coords.WorldPoint;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class DigLogTest
{
	private static final int ORB = 23069;
	/** The last JSON saved, standing in for the RuneLite config. */
	private String saved;
	private final DigLog log = new DigLog(new DigLog.Store()
	{
		@Override
		public String load()
		{
			return saved;
		}

		@Override
		public void save(String json)
		{
			saved = json;
		}
	}, new Gson());

	@Test
	public void aDigThatGivesTheItemIsGood()
	{
		WorldPoint tile = new WorldPoint(3203, 3214, 0);
		log.dug(tile, ORB);
		assertNull(log.tick(false));
		assertEquals(DigLog.Result.GOOD, log.tick(true));
		assertEquals(tile, log.lastTile());
		assertTrue(log.tilesFor(ORB).getGood().contains("3203,3214,0"));
		assertTrue(saved.contains("3203,3214,0"));
	}

	@Test
	public void aDigWithoutTheItemIsAMissUnlessTheTileWorkedBefore()
	{
		WorldPoint tile = new WorldPoint(3200, 3210, 0);
		log.dug(tile, ORB);
		DigLog.Result result = null;
		for (int i = 0; i < DigLog.RESULT_TICKS; i++)
		{
			result = log.tick(false);
		}
		assertEquals(DigLog.Result.MISSED, result);
		assertTrue(log.tilesFor(ORB).getMissed().contains("3200,3210,0"));

		log.dug(tile, ORB);
		log.tick(true);
		assertTrue(log.tilesFor(ORB).getGood().contains("3200,3210,0"));
		assertTrue(log.tilesFor(ORB).getMissed().isEmpty());
	}

	@Test
	public void nothingHappensWithoutADig()
	{
		assertNull(log.tick(true));
		assertEquals(0, log.pendingItem());
	}

	@Test
	public void theAreaIsTheRectangleAroundKnownAndLearnedTiles()
	{
		Guide.Step step = new Guide.Step();
		Guide.Target target = new Guide.Target();
		target.setX(3203);
		target.setY(3213);
		step.setTarget(target);
		step.setDigArea(Arrays.asList(new int[]{3203, 3213}, new int[]{3203, 3212}));
		Guide.Done done = new Guide.Done();
		done.setHaveId(ORB);
		step.setDone(done);
		assertEquals(new Rectangle(3203, 3212, 1, 2), log.area(step));

		// a learned corner two tiles west fills in everything between
		log.dug(new WorldPoint(3201, 3214, 0), ORB);
		log.tick(true);
		assertEquals(new Rectangle(3201, 3212, 3, 3), log.area(step));
	}

	@Test
	public void noAreaWithoutKnownTiles()
	{
		Guide.Step step = new Guide.Step();
		step.setTarget(new Guide.Target());
		assertNull(log.area(step));
	}

	@Test
	public void keysRoundTrip()
	{
		WorldPoint p = new WorldPoint(3077, 3260, 0);
		assertEquals(p, DigLog.parse(DigLog.key(p)));
		assertNull(DigLog.parse("nonsense"));
	}
}

package com.speedrunguide;

import com.google.gson.Gson;
import java.util.Arrays;
import java.util.Collections;
import java.util.List;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.ItemID;
import net.runelite.api.gameval.VarbitID;
import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertNotNull;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class GuideLibraryTest
{
	private final GuideLibrary everything = GuideLibrary.loadAll(new Gson());
	private final GuideLibrary library = GuideLibrary.load(new Gson());

	@Test
	public void bundlesAllFifteenQuests()
	{
		assertEquals(15, everything.all().size());
		assertEquals("X Marks the Spot", everything.all().get(0).getName());
		assertEquals("Dragon Slayer II", everything.all().get(14).getName());
	}

	@Test
	public void onlyRoutedQuestsAreOffered()
	{
		assertEquals(2, library.all().size());
		assertEquals("X Marks the Spot", library.all().get(0).getName());
		assertEquals("Cook's Assistant", library.all().get(1).getName());
		assertNull(library.byName("Dragon Slayer II"));
	}

	@Test
	public void everyGuideMatchesARuneLiteQuest()
	{
		for (Guide g : everything.all())
		{
			assertNotNull(g.getName(), g.quest());
		}
	}

	@Test
	public void everyGuideHasStepsAndTrophyTimes()
	{
		for (Guide g : everything.all())
		{
			assertFalse(g.getName(), g.steps().isEmpty());
			assertTrue(g.getName(), g.getStartStep() < g.steps().size());
			assertEquals(g.getName(), 5, g.getTrophies().size());
			for (Guide.Step s : g.steps())
			{
				assertFalse(g.getName() + " has leftover wikitext: " + s.getText(),
					s.getText().contains("{{") || s.getText().contains("[[") || s.getText().contains("}}"));
			}
		}
	}

	@Test
	public void cooksAssistantStartsWithTheCook()
	{
		Guide cook = library.byName("Cook's Assistant");
		Guide.Step first = cook.steps().get(cook.getStartStep());
		assertEquals("Talk to the Cook in Lumbridge Castle's kitchen.", first.getText());
		assertEquals("1, 1", GuideText.keys(first.getChat()));
		assertEquals("2:00", cook.getTrophies().get("platinum"));
	}

	@Test
	public void routeExtrasAreMerged()
	{
		Guide xMarks = library.byName("X Marks the Spot");
		assertEquals(7, xMarks.steps().size());
		Guide.Step shop = xMarks.steps().get(1);
		assertEquals(Collections.singletonList("Spade"), shop.getShop());
		assertTrue(GuideText.matchesName(shop.getNpcs(), "Shop keeper"));
		assertEquals("Dig here", xMarks.steps().get(2).getTarget().getLabel());
		assertEquals(3230, xMarks.steps().get(2).getTarget().getX());

		Guide cook = library.byName("Cook's Assistant");
		assertTrue(GuideText.matchesName(cook.steps().get(0).getNpcs(), "<col=ffff00>Cook</col>"));
		assertEquals(Collections.singletonList("Egg"), cook.steps().get(3).getGround());
		assertEquals("Trade", cook.steps().get(2).getLeftClick());
		assertEquals(2, cook.steps().get(5).getTarget().getPlane());
	}

	@Test
	public void routeStepsKnowWhenTheyAreDone()
	{
		Guide xMarks = library.byName("X Marks the Spot");
		assertEquals("Spade", xMarks.steps().get(1).getDone().getHave());
		// Each dig is done when the item it gives arrives, so a dig on the wrong tile doesn't count
		assertEquals(ItemID.CLUEQUEST_CLUE2, xMarks.steps().get(2).getDone().getHaveId());
		assertEquals(ItemID.CLUEQUEST_CLUE3, xMarks.steps().get(3).getDone().getHaveId());
		assertEquals(ItemID.CLUEQUEST_CLUE4, xMarks.steps().get(4).getDone().getHaveId());
		assertEquals(ItemID.CLUEQUEST_CASKET, xMarks.steps().get(5).getDone().getHaveId());
		assertEquals(3209, xMarks.steps().get(2).getTarget().getY());

		Guide cook = library.byName("Cook's Assistant");
		// the mill: grain into the hopper, then the lever (Quest Helper's MILL_FLOUR check), then the flour
		assertEquals("Grain", cook.steps().get(5).getDone().getLack());
		assertEquals(Integer.valueOf(VarbitID.MILL_FLOUR), cook.steps().get(6).getDone().getVarbit());
		assertEquals(1, cook.steps().get(6).getDone().getValue());
		assertEquals("Pot of flour", cook.steps().get(7).getDone().getHave());
		assertEquals(3, cook.steps().get(9).getDone().getArrive());
		assertEquals(Arrays.asList("Hopper", "Ladder"), cook.steps().get(5).getObjects());
		// compost is done once bought; emptying it is shown on the egg step
		assertEquals("Compost", cook.steps().get(2).getDone().getHave());
		assertEquals("Empty", cook.steps().get(3).getUseOption());
		assertEquals("south", cook.steps().get(4).getPick());
		// the egg in front of Fred's house is south of the chicken pen ones
		assertEquals("south", cook.steps().get(3).getPick());
		assertEquals(3195, cook.steps().get(2).getTarget().getX());
		assertEquals(Arrays.asList("Egg", "Pot of flour", "Bucket of milk"), cook.steps().get(9).getUse());
		assertEquals(InterfaceID.MagicSpellbook.TELEPORT_HOME_STANDARD, cook.steps().get(9).getWidget());
		assertEquals(Arrays.asList("Egg", "Pot of flour", "Bucket of milk"), cook.steps().get(10).getUse());
		assertEquals(3208, cook.steps().get(0).getSpot().getX());
	}

	@Test
	public void questProgressPicksTheStep()
	{
		Guide xMarks = library.byName("X Marks the Spot");
		assertEquals(Integer.valueOf(VarbitID.CLUEQUEST), xMarks.getProgress().getVarbit());
		// 2 is set after talking to Veos and covers buying the spade and the first dig
		assertEquals(1, xMarks.stepForProgress(2));
		assertArrayEquals(new int[]{1, 3}, xMarks.progressRange(1));
		// a reset puts the value back to 0, which only allows the first step
		assertEquals(0, xMarks.stepForProgress(0));
		assertArrayEquals(new int[]{0, 1}, xMarks.progressRange(0));
		assertEquals(6, xMarks.stepForProgress(7));
		assertArrayEquals(new int[]{6, 7}, xMarks.progressRange(6));
		assertEquals(-1, xMarks.stepForProgress(99));

		Guide cook = library.byName("Cook's Assistant");
		assertEquals(Integer.valueOf(29), cook.getProgress().getVarp());
		assertArrayEquals(new int[]{1, cook.steps().size()}, cook.progressRange(cook.stepForProgress(1)));
	}

	@Test
	public void waypointsLeadTheWayAndLaddersChangeFloors()
	{
		Guide xMarks = library.byName("X Marks the Spot");
		Guide.Step third = xMarks.steps().get(4);
		WorldPoint dig = third.getTarget().worldPoint();
		// from the castle, every waypoint is still ahead
		List<WorldPoint> fromCastle = RouteTracker.goals(third, new WorldPoint(3203, 3213, 0), dig);
		assertEquals(third.getVia().size() + 1, fromCastle.size());
		// halfway there, the passed ones drop off
		List<WorldPoint> halfway = RouteTracker.goals(third, new WorldPoint(3156, 3241, 0), dig);
		assertEquals(new WorldPoint(3139, 3253, 0), halfway.get(0));
		assertEquals(dig, halfway.get(halfway.size() - 1));

		Guide.Step hopper = library.byName("Cook's Assistant").steps().get(5);
		WorldPoint top = hopper.getTarget().worldPoint();
		assertEquals(Collections.singletonList(new WorldPoint(3164, 3307, 0)), RouteTracker.goals(hopper, new WorldPoint(3166, 3300, 0), top));
		assertEquals(Collections.singletonList(new WorldPoint(3164, 3307, 1)), RouteTracker.goals(hopper, new WorldPoint(3165, 3307, 1), top));
		assertEquals(Collections.singletonList(top), RouteTracker.goals(hopper, new WorldPoint(3164, 3307, 2), top));
	}

	@Test
	public void dialogueOptionsMatchLoosely()
	{
		List<Guide.ChatOption> chat = Collections.singletonList(option("1", "What's Wrong?"));
		assertTrue(GuideText.matches(chat, "What's wrong?"));
		assertTrue(GuideText.matches(chat, "<col=ffffff>1. What's wrong?</col>"));
		assertFalse(GuideText.matches(chat, "Can I help?"));
		assertFalse(GuideText.matches(chat, ""));
	}

	@Test
	public void keysUseBulletsForUnnumberedOptions()
	{
		assertEquals("3, •", GuideText.keys(Arrays.asList(option("3", "a"), option("", "b"))));
	}

	@Test
	public void plainStripsTags()
	{
		assertEquals("Talk to <b>Aris</b> & go", GuideText.plain("Talk to &lt;b&gt;<b>Aris</b>&lt;/b&gt; &amp; go"));
	}

	private static Guide.ChatOption option(String key, String text)
	{
		Guide.ChatOption o = new Guide.ChatOption();
		o.setKey(key);
		o.setText(text);
		return o;
	}
}

package com.speedrunguide;

import java.awt.Point;
import java.util.List;
import net.runelite.api.CollisionDataFlag;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class PathfinderTest
{
	private static int[][] open(int size)
	{
		return new int[size][size];
	}

	@Test
	public void walksDiagonallyInTheOpen()
	{
		List<Point> path = Pathfinder.find(open(10), 0, 0, 3, 3, 0);
		assertEquals(3, path.size());
		assertEquals(new Point(3, 3), path.get(2));
	}

	@Test
	public void stopsNextToTheGoalWhenReachIsOne()
	{
		List<Point> path = Pathfinder.find(open(10), 0, 0, 5, 0, 1);
		assertEquals(new Point(4, 0), path.get(path.size() - 1));
	}

	@Test
	public void goesAroundAWall()
	{
		int[][] flags = open(10);
		// a solid column at x = 2 from y = 0 to 7
		for (int y = 0; y <= 7; y++)
		{
			flags[2][y] = CollisionDataFlag.BLOCK_MOVEMENT_FULL;
		}
		List<Point> path = Pathfinder.find(flags, 0, 0, 4, 0, 0);
		assertEquals(new Point(4, 0), path.get(path.size() - 1));
		assertTrue(path.stream().noneMatch(p -> p.x == 2 && p.y <= 7));
	}

	@Test
	public void headsTowardsATargetOutsideTheScene()
	{
		List<Point> path = Pathfinder.find(open(10), 5, 5, 40, 5, 0);
		assertEquals(new Point(9, 5), path.get(path.size() - 1));
	}

	@Test
	public void wallsBlockTheSideTheyAreOn()
	{
		int[][] flags = open(3);
		// a wall on the east side of (1, 1): stepping from (2, 1) west into it is blocked
		flags[1][1] = CollisionDataFlag.BLOCK_MOVEMENT_EAST;
		assertFalse(Pathfinder.canMove(flags, 2, 1, -1, 0));
		assertTrue(Pathfinder.canMove(flags, 1, 0, 0, 1));
	}

	@Test
	public void alreadyThereMeansNoPath()
	{
		assertTrue(Pathfinder.find(open(5), 2, 2, 2, 2, 0).isEmpty());
	}
}

